import {SnakeGame,SnakeWallet,SNAKE_SKINS} from './snake-model.js';
export function mountSnake(root,api){
 root.innerHTML=`<header class="snake-header"><button id="snake-back" type="button" aria-label="게임 선택">←</button><div><small>WORM GARDEN</small><h1>지렁이 정원</h1></div><div class="snake-wallet">🪙 <b id="snake-coins">0</b></div><button id="snake-shop" type="button">🎨 스킨</button></header><div class="snake-stats"><span>점수 <b id="snake-score">0</b></span><span>최고 <b id="snake-best">0</b></span><span>AI 지렁이 4마리</span></div><div class="snake-arena"><canvas id="snake-canvas" width="840" height="720" aria-label="지렁이 게임판. 방향 버튼 또는 화살표 키로 이동하세요."></canvas><div class="snake-overlay" id="snake-overlay"><div><h2 id="snake-title">지렁이 정원</h2><p id="snake-message">먹이를 모으며 AI 지렁이를 피해 보세요!</p><button id="snake-start" type="button">게임 시작</button></div></div></div><p class="snake-tip">방향 버튼이나 화면을 밀어서 움직여요 · 먹이 하나마다 🪙 10 · 자동 저장</p><div class="snake-controls"><button data-snake="up" aria-label="위">▲</button><div><button data-snake="left" aria-label="왼쪽">◀</button><button data-snake="down" aria-label="아래">▼</button><button data-snake="right" aria-label="오른쪽">▶</button></div></div><section id="snake-skins" hidden><div><h2>지렁이 스킨</h2><button id="snake-close" type="button">닫기 ×</button></div><p>지렁이 게임에서 모은 동전으로 구매해요.</p><div id="snake-skin-list"></div></section>`;
 const $=id=>root.querySelector('#'+id),canvas=$('snake-canvas'),ctx=canvas.getContext('2d');let wallet=null,game=null,last=0,lag=0,settled=false,touch=null,creditedScore=0,creditedFood=0,saveProblem=false;
 const active=()=>api.current()==='snake';const safe=fn=>{try{return fn();}catch(e){api.toast(e.message||'저장하지 못했어요.');return false;}};
 function refresh(){if(!wallet)return;$('snake-coins').textContent=wallet.data.coins.toLocaleString();$('snake-best').textContent=wallet.data.best.toLocaleString();$('snake-score').textContent=(game?.score||0).toLocaleString();}
 function checkpoint(){if(!game||settled||game.score===creditedScore&&game.foodEaten===creditedFood)return true;const ok=safe(()=>{wallet.checkpoint(game.id,game.score,game.foodEaten);creditedScore=game.score;creditedFood=game.foodEaten;refresh();return true;});if(!ok){saveProblem=true;$('snake-title').textContent='저장을 확인해 주세요';$('snake-message').textContent='기록을 저장한 뒤 계속할 수 있어요.';$('snake-start').textContent='저장 다시 시도';$('snake-overlay').hidden=false;}return !!ok;}
 function finish(){if(!game||settled)return true;const ok=safe(()=>{wallet.settle(game.id,game.score,game.foodEaten);settled=true;saveProblem=false;creditedScore=game.score;creditedFood=game.foodEaten;refresh();return true;});if(!ok){saveProblem=true;$('snake-title').textContent='저장을 확인해 주세요';$('snake-message').textContent='기록을 저장한 뒤 다시 시작할 수 있어요.';$('snake-start').textContent='저장 다시 시도';$('snake-overlay').hidden=false;return false;}$('snake-title').textContent='이번 판 끝!';$('snake-message').textContent=`${game.score.toLocaleString()}점 · 지렁이 동전 ${game.score.toLocaleString()}개 획득`; $('snake-start').textContent='다시 시작';$('snake-overlay').hidden=false;api.active(false);return true;}
 function start(){if(saveProblem&&game?.phase==='playing'){if(!checkpoint())return;saveProblem=false;$('snake-overlay').hidden=true;api.active(true);return;}if(game&&!settled&&!finish())return;game=new SnakeGame();settled=false;creditedScore=0;creditedFood=0;saveProblem=false;lag=0;last=0;$('snake-overlay').hidden=true;$('snake-skins').hidden=true;api.active(true);refresh();draw();}
 function draw(){const w=canvas.width,h=canvas.height,cols=game?.width||28,rows=game?.height||24,cell=w/cols,blend=Math.max(0,Math.min(1,lag/.13));ctx.fillStyle='#111c2b';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#74aeb313';ctx.lineWidth=1;for(let x=0;x<=cols;x++){ctx.beginPath();ctx.moveTo(x*cell,0);ctx.lineTo(x*cell,h);ctx.stroke();}for(let y=0;y<=rows;y++){ctx.beginPath();ctx.moveTo(0,y*cell);ctx.lineTo(w,y*cell);ctx.stroke();}if(!game)return;
  const foodColors=['#ffcf78','#ff7eaa','#a2ee86','#7ed9ff','#d7a7ff'];for(const f of game.food){const x=(f.x+.5)*cell,y=(f.y+.5)*cell,color=foodColors[(f.x*7+f.y*3)%foodColors.length];ctx.fillStyle=color;ctx.globalAlpha=.18;ctx.beginPath();ctx.arc(x,y,cell*.34,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.beginPath();ctx.arc(x,y,cell*.14,0,Math.PI*2);ctx.fill();}
  const skin=SNAKE_SKINS.find(s=>s.id===wallet.data.skin)||SNAKE_SKINS[0];for(const snake of game.all()){const color=snake.player?skin.color:snake.color,body=snake.body.map((p,i)=>{const prev=snake.previousBody?.[i]||p;return {x:prev.x+(p.x-prev.x)*blend,y:prev.y+(p.y-prev.y)*blend};});if(!body.length)continue;ctx.strokeStyle=color;ctx.lineWidth=cell*.76;ctx.lineJoin='round';ctx.lineCap='round';ctx.beginPath();ctx.moveTo((body[0].x+.5)*cell,(body[0].y+.5)*cell);for(const p of body.slice(1))ctx.lineTo((p.x+.5)*cell,(p.y+.5)*cell);ctx.stroke();for(let i=body.length-1;i>=0;i--){const p=body[i],x=(p.x+.5)*cell,y=(p.y+.5)*cell;ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,cell*(i===0?.45:.36),0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffffff24';ctx.beginPath();ctx.arc(x-cell*.1,y-cell*.13,cell*.13,0,Math.PI*2);ctx.fill();}const head=body[0],dir=snake.dir,x=(head.x+.5)*cell,y=(head.y+.5)*cell;for(const side of [-1,1]){const ex=x+(dir.x*.13-dir.y*.19*side)*cell,ey=y+(dir.y*.13+dir.x*.19*side)*cell;ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(ex,ey,cell*.11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#14253a';ctx.beginPath();ctx.arc(ex+dir.x*cell*.035,ey+dir.y*cell*.035,cell*.055,0,Math.PI*2);ctx.fill();}}
 }

 function renderShop(){$('snake-skin-list').replaceChildren();for(const s of SNAKE_SKINS){const button=document.createElement('button');button.type='button';const owned=wallet.data.owned.includes(s.id);button.innerHTML=`<i style="background:${s.color}"></i><strong>${s.name}</strong><small>${wallet.data.skin===s.id?'사용 중':owned?'선택하기':'🪙 '+s.price}</small>`;button.disabled=wallet.data.skin===s.id;button.onclick=()=>safe(()=>{wallet.buy(s.id);renderShop();refresh();draw();});$('snake-skin-list').append(button);}}
 $('snake-shop').onclick=()=>{if(!wallet)return;$('snake-skins').hidden=false;renderShop();};$('snake-close').onclick=()=>{$('snake-skins').hidden=true;};$('snake-back').onclick=()=>api.open('game-picker-dialog');$('snake-start').onclick=start;
 const dirs={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};root.querySelectorAll('[data-snake]').forEach(b=>b.onclick=()=>game?.turn(...dirs[b.dataset.snake]));globalThis.addEventListener('keydown',e=>{if(!active()||document.querySelector('dialog[open]'))return;const k={ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'}[e.key];if(k){e.preventDefault();game?.turn(...dirs[k]);}});
 function drag(e){if(!touch||touch.id!==e.pointerId)return;const dx=e.clientX-touch.x,dy=e.clientY-touch.y;if(Math.max(Math.abs(dx),Math.abs(dy))<12)return;game?.turn(...dirs[Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up']);touch.x=e.clientX;touch.y=e.clientY;}
 canvas.addEventListener('pointerdown',e=>{if(!active()||!game||game.phase!=='playing')return;touch={id:e.pointerId,x:e.clientX,y:e.clientY};try{canvas.setPointerCapture(e.pointerId);}catch{}});canvas.addEventListener('pointermove',drag);canvas.addEventListener('pointerup',e=>{drag(e);if(touch?.id===e.pointerId)touch=null;});canvas.addEventListener('pointercancel',e=>{if(touch?.id===e.pointerId)touch=null;});canvas.addEventListener('lostpointercapture',e=>{if(touch?.id===e.pointerId)touch=null;});
 globalThis.addEventListener('pagehide',()=>{if(active())checkpoint();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&active())checkpoint();});

 function frame(now){const dt=last?Math.min(.2,(now-last)/1000):0;last=now;if(active()&&game?.phase==='playing'&&!saveProblem&&!document.hidden&&!document.querySelector('dialog[open]')&&$('snake-skins').hidden){lag+=dt;while(lag>=.13&&game.phase==='playing'&&!saveProblem){game.step();lag-=.13;if(!checkpoint())break;}refresh();draw();if(game.phase==='over'&&!saveProblem)finish();}requestAnimationFrame(frame);}requestAnimationFrame(frame);
 return {select(){wallet=new SnakeWallet();game=null;settled=false;creditedScore=0;creditedFood=0;saveProblem=false;touch=null;$('snake-title').textContent='지렁이 정원';$('snake-message').textContent='먹이를 모으며 AI 지렁이를 피해 보세요!';$('snake-start').textContent='게임 시작';$('snake-overlay').hidden=false;$('snake-skins').hidden=true;api.active(false);refresh();draw();},leave(){if(game&&!settled&&!finish())return false;touch=null;api.active(false);return true;},save(){return checkpoint();},restart:start,openLocker(){if(wallet){$('snake-skins').hidden=false;renderShop();}},openRecords(){api.toast(`최고 기록 ${wallet?.data.best||0}점`);},model:()=>game,focusMode(){api.toast('먹이를 모으며 AI 지렁이와 겨뤄요!');},mode:()=> 'classic'};
}
